async function readingPage(reference, env, request) {
  const requestLocale = deliveryLocale({}, request);
  const requestUi = deliveryUi(requestLocale);
  if (!reference) return htmlResponse(errorShell(requestUi.referenceMissing, requestLocale), 400);
  const resolved = await resolvePaidReadingReference(reference, env);
  const locale = deliveryLocale(resolved.draft || {}, request);
  const ui = deliveryUi(locale);
  if (!resolved.orderId) return htmlResponse(errorShell(ui.referenceExpired, locale), 404);
  if (resolved.requiresSecureAccess) {
    return htmlResponse(errorShell(ui.secureRequired, locale), 403);
  }
  if (resolved.secure && paidQuestionReviewOpen(resolved.draft)) {
    return htmlResponse(paidQuestionReviewShell(resolved.draft, locale));
  }
  const orderId = resolved.orderId;
  // Delivery generation belongs to the lease-backed background queue. A
  // customer opening their secure URL must never start (or wait for) another
  // model run: that previously kept the request open until Vercel's timeout
  // and produced a 504 even while the queued delivery was progressing.
  const reading = await env.READINGS_CACHE.get(`reading:${orderId}`, "json");
  if (!reading || (!reading.html && !(reading.readings && reading.readings.length))) {
    const draftCreatedAt = Number(resolved.draft && resolved.draft.createdAt) || Date.now();
    const estimatedDeliverAt = draftCreatedAt + readingDeliveryDelayMinutes(orderId, env) * 6e4;
    return htmlResponse(preparingShell({
      deliverAt: Math.max(Date.now() + 6e4, estimatedDeliverAt)
    }, reference, locale));
  }
  const readingLocaleValue = deliveryLocale(reading, request);
  if (reading.deliverAt && Date.now() < reading.deliverAt) {
    return htmlResponse(preparingShell(reading, reference, readingLocaleValue));
  }
  return htmlResponse(readingShell(reading, reference, readingLocaleValue));
}
