async function activateMembership(order, env) {
  const cid = order.customer && order.customer.id;
  if (!cid) return;
  const store = shopifyStoreDomain(env);
  const ver = env.API_VERSION || "2026-07";
  const H = { "Content-Type": "application/json" };
  const res = await shopifyAdminFetch(`https://${store}/admin/api/${ver}/customers/${cid}.json?fields=id,tags`, { headers: H }, env);
  if (!res.ok) return;
  const c = (await res.json()).customer || {};
  const tags = String(c.tags || "").split(",").map((s) => s.trim()).filter(Boolean);
  if (!tags.some((t) => t.toLowerCase() === MEMBER_TAG)) {
    tags.push(MEMBER_TAG);
    await shopifyAdminFetch(`https://${store}/admin/api/${ver}/customers/${cid}.json`, {
      method: "PUT",
      headers: H,
      body: JSON.stringify({ customer: { id: cid, tags: tags.join(", ") } })
    }, env);
  }
  await env.READINGS_CACHE.put(`memberexp:${cid}`, String(Date.now() + 32 * 24 * 3600 * 1e3), {
    expirationTtl: 60 * 60 * 24 * 60
  });
  try {
    const email = String(order.email || order.contact_email || "").trim();
    if (email.includes("@") && NL_SENDONE && env.NL_SECRET) {
      const locale = orderCustomerContext(order).locale;
      const language = customerLanguage(locale);
      const isEs = language === "es";
      const isDe = language === "de";
      const pick = (en, es, de) => isEs ? es : isDe ? de : en;
      await fetch(`${NL_SENDONE}?key=${env.NL_SECRET}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          to: email,
          replyTo: "acadezone@gmail.com",
          subject: pick("Welcome to the Reading Club", "Te damos la bienvenida al Reading Club", "Willkommen im Reading Club"),
          html: ppWrap(
            `<p>${pick("Hi there,", "Hola:", "Hallo,")}</p><p>${pick("Welcome to the Reading Club. From today you can ask up to fifteen questions a month and receive one full In-Depth reading each month.", "Te damos la bienvenida al Reading Club. Desde hoy puedes hacer hasta quince preguntas al mes y recibir una lectura completa en profundidad cada mes.", "Willkommen im Reading Club. Ab heute kannst du bis zu 15 Fragen pro Monat stellen und jeden Monat eine vollständige vertiefte Deutung erhalten.")}</p>` + ppBtn(`https://deckaura.com${storefrontPath(locale, "/pages/reading-club")}`, pick("Ask my first question &rarr;", "Hacer mi primera pregunta &rarr;", "Meine erste Frage stellen &rarr;")) + `<p style="font-size:14px;color:#6f679a">${pick("Bookmark that page, it is your member door. Make sure you are signed in with this email address.", "Guarda esa página: es tu acceso para miembros. Asegúrate de iniciar sesión con esta dirección de correo.", "Speichere diese Seite; sie ist dein Mitgliederzugang. Stelle sicher, dass du mit dieser E-Mail-Adresse angemeldet bist.")}</p>`,
            locale
          )
        })
      });
    }
  } catch (e) {
  }
}
