async function sweepMemberships(env, opts = {}) {
  const list = await env.READINGS_CACHE.list({ prefix: "memberexp:" });
  const now = Date.now();
  const limit = Math.max(1, Math.min(Number.parseInt(String(opts.limit || 1e3), 10) || 1e3, 1e3));
  const deadlineMs = Number.isFinite(Number(opts.deadlineMs)) ? Number(opts.deadlineMs) : Number.POSITIVE_INFINITY;
  const store = shopifyStoreDomain(env);
  const ver = env.API_VERSION || "2026-07";
  const H = { "Content-Type": "application/json" };
  let scanned = 0;
  let attempted = 0;
  let removed = 0;
  let failed = 0;
  for (const key of list.keys) {
    if (attempted >= limit || Date.now() >= deadlineMs - 1e3) break;
    scanned += 1;
    const exp = parseInt(await env.READINGS_CACHE.get(key.name), 10) || 0;
    if (exp > now) continue;
    attempted += 1;
    const cid = key.name.slice("memberexp:".length);
    try {
      const requestTimeout = Number.isFinite(deadlineMs)
        ? Math.max(500, Math.min(1e4, deadlineMs - Date.now() - 500))
        : 1e4;
      const res = await shopifyAdminFetch(`https://${store}/admin/api/${ver}/customers/${cid}.json?fields=id,tags`, {
        headers: H,
        signal: AbortSignal.timeout(requestTimeout)
      }, env);
      if (res.status === 404) {
        await env.READINGS_CACHE.delete(key.name);
        removed += 1;
        continue;
      }
      if (res.ok) {
        const c = (await res.json()).customer || {};
        const tags = String(c.tags || "").split(",").map((s) => s.trim()).filter(Boolean).filter((t) => t.toLowerCase() !== MEMBER_TAG);
        const updateTimeout = Number.isFinite(deadlineMs)
          ? Math.max(500, Math.min(1e4, deadlineMs - Date.now() - 500))
          : 1e4;
        const update = await shopifyAdminFetch(`https://${store}/admin/api/${ver}/customers/${cid}.json`, {
          method: "PUT",
          headers: H,
          body: JSON.stringify({ customer: { id: cid, tags: tags.join(", ") } }),
          signal: AbortSignal.timeout(updateTimeout)
        }, env);
        if (!update.ok) {
          failed += 1;
          continue;
        }
      } else {
        failed += 1;
        continue;
      }
      await env.READINGS_CACHE.delete(key.name);
      removed += 1;
    } catch (e) {
      failed += 1;
    }
  }
  return {
    scanned,
    attempted,
    removed,
    failed,
    deadlineReached: Date.now() >= deadlineMs - 1e3
  };
}
