function cors(res, request) {
  const requestOrigin = request ? String(request.headers.get("Origin") || "").toLowerCase() : "";
  const responseOrigin = STOREFRONT_ORIGINS.has(requestOrigin) ? requestOrigin : ALLOWED_ORIGIN;
  res.headers.set("Access-Control-Allow-Origin", responseOrigin);
  res.headers.set("Access-Control-Allow-Methods", "POST, GET, OPTIONS");
  res.headers.set("Access-Control-Allow-Headers", "Content-Type");
  res.headers.set("Access-Control-Max-Age", "86400");
  res.headers.append("Vary", "Origin");
  res.headers.set("X-Content-Type-Options", "nosniff");
  res.headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  return res;
}
function funnelCors(res) {
  // Shopify custom pixels run in an opaque sandbox and legitimately send
  // Origin: null. This telemetry route is credentialless and stores only the
  // bounded allowlisted schema above, so a wildcard is both interoperable and
  // safer than reflecting arbitrary origins. No credential header is emitted.
  res.headers.set("Access-Control-Allow-Origin", "*");
  res.headers.set("Access-Control-Allow-Methods", "POST, OPTIONS");
  res.headers.set("Access-Control-Allow-Headers", "Content-Type");
  res.headers.set("Access-Control-Max-Age", "86400");
  res.headers.set("Cache-Control", "no-store");
  res.headers.set("X-Content-Type-Options", "nosniff");
  res.headers.set("Referrer-Policy", "no-referrer");
  return res;
}
